        await waitForResources({
          page: page,
          names: resources.map((file) => path.basename(file.name))
        })
        break
      }
      case 'keep both': {
        await page.locator(util.format(actionConfirmationButton, 'Keep both')).click()
        await page.locator(uploadInfoCloseButton).click()

        await waitForResources({
          page: page,
          names: resources.map((file) => path.basename(file.name))
        })
        break
      }
    }
  } else {
    await page.locator(uploadInfoCloseButton).click()

    await waitForResources({
      page: page,
      names: resources.map((file) => path.basename(file.name))
    })
  }
}

