  defaultComponentMocks,
  defaultPlugins,
  defaultStoreMockOptions,
  defaultStubs,
  mount
} from 'web-test-helpers'
import { mock } from 'jest-mock-extended'
import { Resource, SpaceResource } from 'web-client/src/helpers'
import ContextActions from 'web-app-files/src/components/FilesList/ContextActions.vue'

const mixins = [
  '$_acceptShare_items',
  '$_downloadArchive_items',
  '$_move_items',
  '$_copy_items',
  '$_emptyTrashBin_items',
  '$_fileActions_editorActions',
  '$_showShares_items',
  '$_createQuicklink_items',
  '$_downloadArchive_items',
  '$_downloadFile_items',
  '$_delete_items',
  '$_move_items',
  '$_copy_items',
  '$_paste_items',
  '$_rename_items',
  '$_restore_items',
  '$_declineShare_items',
  '$_setSpaceImage_items',
  '$_setSpaceReadme_items',
  '$_navigate_space_items',
  '$_navigate_items',
  '$_favorite_items',
  '$_showDetails_items',
  '$_showEditTags_items'
]

const Component = {
  ...ContextActions,
  mixins
}

describe('ContextActions', () => {
  describe('menu sections', () => {
    it('do not render when no action enabled', () => {
      const { wrapper } = getWrapper()
      expect(wrapper.findAll('action-menu-item-stub').length).toBe(0)
    })

    it('render enabled actions', () => {
      const enabledActions = [
        '$_acceptShare_items',
        '$_createQuicklink_items',
        '$_rename_items',
        '$_fileActions_editorActions'
      ]
      const { wrapper } = getWrapper({ enabledActions })
      expect(wrapper.findAll('action-menu-item-stub').length).toBe(enabledActions.length)
    })
  })
})

function getWrapper({ enabledActions = [] } = {}) {
  const storeOptions = { ...defaultStoreMockOptions }
  storeOptions.modules.Files.getters.currentFolder.mockImplementation(() => '/')
  const store = createStore(storeOptions)
  const mocks = {
    ...defaultComponentMocks(),
    ...getMixinMocks(enabledActions)
  }
  return {
    storeOptions,
    mocks,
    wrapper: mount(Component, {
      props: {
        space: mock<SpaceResource>(),
        items: [mock<Resource>()]
      },
      global: {
        mocks,
        provide: { currentSpace: mock<SpaceResource>() },
        stubs: { ...defaultStubs, 'action-menu-item': true },
        plugins: [...defaultPlugins(), store]
      }
    })
  }
}

const getMixinMocks = (enabledActions) => {
  const mixinMocks = {
    $_fileActions_loadExternalAppActions: jest.fn(() => [
      { isEnabled: () => false, name: '', items: [] }
    ])
  }
  for (const mixin of mixins) {
    const isEnabled = !!enabledActions.includes(mixin)
    mixinMocks[mixin] = [{ isEnabled: () => isEnabled, name: '', items: [] }]
  }
  return mixinMocks
}

import KeyboardActions from '../../../../src/components/FilesList/KeyboardActions.vue'
import { mock } from 'jest-mock-extended'
import { Resource, SpaceResource } from 'web-client/src/helpers'
import { eventBus } from 'web-pkg'
import keycode from 'keycode'

import { defaultStoreMockOptions } from 'web-test-helpers/src/mocks/store/defaultStoreMockOptions'
import { createStore, defaultPlugins, mount } from 'web-test-helpers'
import { useScrollToMock } from 'web-app-files/tests/mocks/useScrollToMock'
import { useScrollTo } from 'web-app-files/src/composables/scrollTo'

jest.mock('web-app-files/src/composables/scrollTo')

describe('KeyboardActions', () => {
  afterEach(() => {
    document.getSelection().empty()
    document.getSelection().removeAllRanges()
  })
  describe('on mount', () => {
    it('subscribes to click events', () => {
      const subscribeSpy = jest.spyOn(eventBus, 'subscribe')
      getWrapper()
      expect(subscribeSpy).toHaveBeenCalledTimes(3)
    })
    it('adds an event listener to the keybind element if given', () => {
      const keybindOnElementId = 'keybind-id'
      document.body.innerHTML = `<div id="${keybindOnElementId}"></div>`
      const element = document.getElementById(keybindOnElementId)
      const subscribeSpy = jest.spyOn(element, 'addEventListener')
      getWrapper({ props: { keybindOnElementId } })
      expect(subscribeSpy).toHaveBeenCalled()
    })
  })
  describe('custom key bindings', () => {
    const id = 'element-id'

    it.each(['textarea', 'input', 'select'])(
      'are enabled for textarea, input and select elements',
      (elType) => {
        document.body.innerHTML = `<${elType} id="${id}">`
        const element = document.getElementById(id)
        element.focus()

        const { wrapper } = getWrapper()
        const enabled = wrapper.vm.areCustomKeyBindingsEnabled()
        expect(enabled).toBeTruthy()
      }
    )
    it('are enabled when the focused element has a specific data tag', () => {
      document.body.innerHTML = `<div data-custom-key-bindings="true" id="${id}">`
      const element = document.getElementById(id)
      const sel = window.getSelection()
      const range = document.createRange()
      range.selectNodeContents(element)
      sel.addRange(range)
      element.focus()

      const { wrapper } = getWrapper()
      const enabled = wrapper.vm.areCustomKeyBindingsEnabled()
      expect(enabled).toBeTruthy()
    })
    it('are disabled without a selected element', () => {
      document.body.innerHTML = `<div id="${id}">`
      const element = document.getElementById(id)
      element.focus()

      const { wrapper } = getWrapper()
      const enabled = wrapper.vm.areCustomKeyBindingsEnabled()
      expect(enabled).toBeFalsy()
    })
  })
  describe('global shortcuts', () => {
    beforeEach(() => {
      document.body.innerHTML =
        '<table>' +
        '<tr class="oc-tbody-tr" data-item-id="0"><td></td></tr>' +
        '<tr class="oc-tbody-tr" data-item-id="1"><td></td></tr>' +
        '<tr class="oc-tbody-tr" data-item-id="2"><td></td></tr>' +
        '</table>'
    })

    it('copy selected files', () => {
      const event = new KeyboardEvent('keyDown', {
        keyCode: keycode('c'),
        metaKey: true,
        ctrlKey: true
      })
      const { wrapper, storeOptions } = getWrapper()
      wrapper.vm.handleGlobalShortcuts(event)
      expect(storeOptions.modules.Files.actions.copySelectedFiles).toHaveBeenCalled()
    })
    it('cut selected files', () => {
      const event = new KeyboardEvent('keyDown', {
        keyCode: keycode('x'),
        metaKey: true,
        ctrlKey: true
      })
      const { wrapper, storeOptions } = getWrapper()
      wrapper.vm.handleGlobalShortcuts(event)
      expect(storeOptions.modules.Files.actions.cutSelectedFiles).toHaveBeenCalled()
    })
    it('paste selected files', () => {
      const event = new KeyboardEvent('keyDown', {
        keyCode: keycode('v'),
        metaKey: true,
        ctrlKey: true
      })
      const { wrapper, storeOptions } = getWrapper()
      wrapper.vm.handleGlobalShortcuts(event)
      expect(storeOptions.modules.Files.actions.pasteSelectedFiles).toHaveBeenCalled()
    })
    it('select all files', () => {
      const event = new KeyboardEvent('keyDown', {
        keyCode: keycode('a'),
        metaKey: true,
        ctrlKey: true
      })
      const { wrapper, storeOptions } = getWrapper()
      wrapper.vm.handleGlobalShortcuts(event)
      expect(storeOptions.modules.Files.mutations.SET_FILE_SELECTION).toHaveBeenCalled()
    })
    it.each(['down', 'up'])('navigate via up and down keys', (key) => {
      const event = new KeyboardEvent('keyDown', { keyCode: keycode(key) })
      const { wrapper, storeOptions } = getWrapper()
      wrapper.vm.handleGlobalShortcuts(event)
      expect(storeOptions.modules.Files.actions.resetFileSelection).toHaveBeenCalled()
      expect(storeOptions.modules.Files.mutations.ADD_FILE_SELECTION).toHaveBeenCalled()
    })
    it.each(['down', 'up'])('navigate via shift + up and down keys', (key) => {
      const event = new KeyboardEvent('keyDown', { keyCode: keycode(key), shiftKey: true })
      const { wrapper, storeOptions } = getWrapper({ latestSelectedId: 1 })
      wrapper.vm.handleGlobalShortcuts(event)
      expect(storeOptions.modules.Files.mutations.ADD_FILE_SELECTION).toHaveBeenCalled()
    })
    it('reset the file selection via esc', () => {
      const event = new KeyboardEvent('keyDown', { keyCode: keycode('esc') })
      const { wrapper, storeOptions } = getWrapper()
      wrapper.vm.handleGlobalShortcuts(event)
      expect(storeOptions.modules.Files.actions.resetFileSelection).toHaveBeenCalled()
    })
  })
  describe('shift + click action', () => {
    const resourceId = '1'
    beforeEach(() => {
      document.body.innerHTML = `<table><tr class="oc-tbody-tr" data-item-id="${resourceId}"><td></td></tr></table>`
    })

    it('adds the clicked file to the current selection', () => {
      const { wrapper, storeOptions } = getWrapper()
      wrapper.vm.handleShiftClickAction(mock<Resource>({ id: resourceId }))
      expect(storeOptions.modules.Files.mutations.ADD_FILE_SELECTION).toHaveBeenCalled()
      expect(storeOptions.modules.Files.mutations.SET_LATEST_SELECTED_FILE_ID).toHaveBeenCalled()
    })
  })
  describe('ctrl + click action', () => {
    it('toggles the file selection', () => {
      const { wrapper, storeOptions } = getWrapper()
      wrapper.vm.handleCtrlClickAction(mock<Resource>())
      expect(storeOptions.modules.Files.actions.toggleFileSelection).toHaveBeenCalled()
    })
  })
  describe('local shortcuts', () => {
    it('toggle the file selection on space key', () => {
      const event = new KeyboardEvent('keyDown', { keyCode: keycode('space') })
      const { wrapper, storeOptions } = getWrapper()
      wrapper.vm.handelLocalShortcuts(event)
      expect(storeOptions.modules.Files.actions.toggleFileSelection).toHaveBeenCalled()
    })
  })
})

const getWrapper = ({ props = {}, latestSelectedId = undefined } = {}) => {
  jest.mocked(useScrollTo).mockImplementation(() => useScrollToMock())

  const storeOptions = defaultStoreMockOptions
  storeOptions.modules.Files.state.latestSelectedId = latestSelectedId
  const store = createStore(storeOptions)
  return {
    storeOptions,
    wrapper: mount(KeyboardActions, {
      props: { paginatedResources: [], space: mock<SpaceResource>(), ...props },
      global: {
        plugins: [...defaultPlugins(), store]
      }
    })
  }
}

import ListInfo from '../../../../src/components/FilesList/ListInfo.vue'
import { defaultPlugins, shallowMount } from 'web-test-helpers'

describe('ListInfo', () => {
  describe('files and folders prop', () => {
    const wrapper = getWrapper()
    const itemElement = wrapper.find('p')

    it('should set data test attributes', () => {
      expect(itemElement.attributes('data-test-items')).toBe('5')
      expect(itemElement.attributes('data-test-files')).toBe('2')
      expect(itemElement.attributes('data-test-folders')).toBe('3')
      expect(itemElement.attributes('data-test-spaces')).toBe('1')
    })

    it('should show text with files and folders total and individual count', () => {
      expect(itemElement.text()).toBe('5 items in total (2 files, 3 folders)')
    })

    describe('item noun used inside information text', () => {
      it.each([
        {
          prop: { files: -1, folders: -1 },
          expectedText: '-2 items in total (-1 files, -1 folders)'
        },
        {
          prop: { files: 0.1, folders: 0.1 },
          expectedText: '0.2 items in total (0.1 files, 0.1 folders)'
        },
        { prop: { files: 0, folders: 0 }, expectedText: '0 items in total (0 files, 0 folders)' },
        { prop: { files: 0, folders: 1 }, expectedText: '1 item in total (0 files, 1 folder)' },
        { prop: { files: 1, folders: 0 }, expectedText: '1 item in total (1 file, 0 folders)' },
        { prop: { files: 1, folders: 1 }, expectedText: '2 items in total (1 file, 1 folder)' },
        { prop: { files: 2, folders: 2 }, expectedText: '4 items in total (2 files, 2 folders)' }
      ])('should be singular or plural according to item, files and folders count', (cases) => {
        const wrapper = getWrapper(cases.prop)
        const itemElement = wrapper.find('p')
        expect(itemElement.text()).toBe(cases.expectedText)
      })
    })
  })
  describe('size prop', () => {
    it('should not set the size attribute if not provided', () => {
      const wrapper = getWrapper()
      const itemElement = wrapper.find('p')

      expect(itemElement.attributes('data-test-size')).toBe(undefined)
    })
    it.each([-1, 0, 1, 0.1, 100000.01])(
      'should set data test size property if provided',
      (size) => {
        const wrapper = getWrapper({ size: size })

        expect(wrapper.find('p').attributes('data-test-size')).toBe(size.toString())
      }
    )

    describe('when size prop is zero or smaller', () => {
      it.each([0, -1])('should not contain size information inside text', (size) => {
        const wrapper = getWrapper({ size: size })
        const itemElement = wrapper.find('p')
        expect(itemElement.text()).toBe('5 items in total (2 files, 3 folders)')
      })
    })
    describe('when size prop is greater than zero', () => {
      it.each`
        size              | expectedSize
        ${0.1}            | ${'0 B'}
        ${1}              | ${'1 B'}
        ${100}            | ${'100 B'}
        ${10000}          | ${'10 kB'}
        ${10000000}       | ${'10 MB'}
        ${10000000000}    | ${'10 GB'}
        ${10000000000000} | ${'10 TB'}
      `('should calculate size units', ({ size, expectedSize }) => {
        const wrapper = getWrapper({ size: size })

        expect(wrapper.find('p').text()).toBe(
          `5 items with ${expectedSize} in total (2 files, 3 folders)`
        )
      })
    })
  })
})

function getWrapper(props = {}) {
